!function(e){function p(p){for(var a,i,d=p[0],o=p[1],m=p[2],f=0,s=[];f<d.length;f++)i=d[f],Object.prototype.hasOwnProperty.call(t,i)&&t[i]&&s.push(t[i][0]),t[i]=0;for(a in o)Object.prototype.hasOwnProperty.call(o,a)&&(e[a]=o[a]);for(c&&c(p);s.length;)s.shift()();return n.push.apply(n,m||[]),r()}function r(){for(var e,p=0;p<n.length;p++){for(var r,i=n[p],d=!0,o=1;o<i.length;o++)r=i[o],0!==t[r]&&(d=!1);d&&(n.splice(p--,1),e=a(a.s=i[0]))}return e}function a(p){if(i[p])return i[p].exports;var r=i[p]={i:p,l:!1,exports:{}};return e[p].call(r.exports,r,r.exports,a),r.l=!0,r.exports}var i={},t={76:0},n=[];a.m=e,a.c=i,a.d=function(e,p,r){a.o(e,p)||Object.defineProperty(e,p,{enumerable:!0,get:r})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,p){if(1&p&&(e=a(e)),8&p)return e;if(4&p&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(a.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&p&&"string"!=typeof e)for(var i in e)a.d(r,i,function(p){return e[p]}.bind(null,i));return r},a.n=function(e){var p=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(p,"a",p),p},a.o=function(e,p){return Object.prototype.hasOwnProperty.call(e,p)},a.p="";var d=window.webpackJsonp=window.webpackJsonp||[],o=d.push.bind(d);d.push=p,d=d.slice();for(var m=0;m<d.length;m++)p(d[m]);var c=o;n.push([148,0]),r()}({148:function(e,p,r){"use strict";r.r(p);var a=r(0);Object(a.a)("de","army",r(149),r(1))},149:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轮式装甲车","link":"de_army#de_army_wav"}],"model":"Sdkfz 234型8轮重型装甲车","description":"<p>德军Sdkfz 234型8轮重型装甲车是德军在1940年就开始研制的用来替代Sdkfz 231型8轮系列（231、232、233、263）装甲车的一种新型轮式装甲车，但由于研制过程缓慢，直到1943才完成车体研制，从1943年底到1945年，陆续生产了具有不同功能的四种装甲车，分别是：Sdkfz 234/1型8轮装甲侦察车、Sdkfz 231/2型8轮装甲侦察车、Sdkfz 231/3型8轮装甲火力支援车和Sdkfz 231/4型8轮装甲反坦克炮车。Sdkfz 234采用了一体式车体设计，车身长度、宽度与Sdkfz 231差不多，但高度比Sdkfz 231矮，因此目标更小；该型车的重量接近12吨，具有更厚的装甲防护和更强的恶劣环境适应能力，此外该型车还配备了更大功率的发动机，除了保持每小时90千米的高速外，其最大行程还达到1000千米。</p><p>1943年9月，Sdkfz 231/2型8轮装甲侦察车开始产出，至1944年9月共生产了101辆；Sdkfz 234/1型8轮装甲侦察车是在1944年6月开始投产，至1945年1月共生产了200辆；而Sdkfz 231/3型8轮装甲火力支援车只在1944年生产了88辆；Sdkfz 231/4型8轮装甲反坦克炮车是最后投产，从1944年12月到1945年3月一共生产了89辆。这些轮式战车大多出现在1944年后西线的各战场中。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_wav234_11.jpg","description":"<h6>Sdkfz 234/1型8轮装甲侦察车</h6><p></p><p>技术数据：</p><p>车长：5.86米，车宽：2.33米，车高：2.1米；自重：5.8吨，战斗全重：11.5吨。</p><p>发动机功率：210马力，最高车速：90千米/小时，最大行程：1000千米。</p><p>装甲厚度：车身与炮塔正面：30毫米，侧、后部：8～10毫米。</p><p>武器配备：1门KWK 38型20毫米机关炮（备弹480发），一挺MG42型7.92毫米并列机枪（备弹2400发）。</p><p>核载乘员4人，1名驾驶员，1名车长，1名炮手和1名无线通讯员。</p>","caption":""},{"image":"imgs/de/army/de_army_wav234_12.jpg","description":"<h6>Sdkfz 234/2型“美洲狮”8轮装甲侦察车</h6><p></p><p>技术数据：</p><p>车长：6.8米，车宽：2.33米，车高：2.38米；自重：5.9吨，战斗全重：11.74吨。发动机功率：210马力，最高车速：90千米/小时，最大行程：1000千米。</p><p>装甲厚度：车身与炮塔：10～30毫米。</p><p>武器配备：1门KWK 39 L/60型50毫米火炮（备弹55发），一挺MG42型7.92毫米并列机枪（备弹1050发）。</p><p>核载乘员：4人，1名驾驶员，1名车长（兼通讯），1名炮手和1名弹药手。</p>","caption":""},{"image":"imgs/de/army/de_army_wav234_13.jpg","description":"<h6>Sdkfz 234/3型8轮装甲火力支援车</h6><p></p><p>技术数据：</p><p>车长：5.86米，车宽：2.33米，车高：2.213米；自重：5.8吨，战斗全重：11.5吨。发动机功率：210马力，最高车速：90千米/小时，最大行程：1000千米。</p><p>装甲厚度：车身：10～30毫米，炮塔四边：14.5毫米。</p><p>武器配备：1门KWK 51 L/24型75毫米榴弹炮（备弹50发），一挺MG42型7.92毫米并列机枪（备弹1050发）。（注：Sdkfz 234/3为开放式炮塔）</p><p>核载乘员：4人，1名驾驶员，1名车长（兼通讯），1名炮手和1名弹药手。</p>","caption":""},{"image":"imgs/de/army/de_army_wav234_14.jpg","description":"<h6>Sdkfz 234/4型8轮装甲反坦克炮车</h6><p></p><p>技术数据：</p><p>车长：6.84米，车宽：2.33米，车高：2.35米；战斗全重11.55吨。</p><p>发动机功率：210马，最高车速：90千米/小时，最大行程：1000千米。</p><p>装甲厚度：10～30毫米。</p><p>武器配备：1门PAK 40 L/46型75毫米火炮（备弹12发），炮塔为敞开式，火炮正面有防盾。</p>","caption":""}],"part2title":"战场上的Sdkfz 234型8轮重型装甲车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_wav234_21.jpg","description":"1945年4月，东线战场匈牙利地区，隶属德国武装党卫军第16“党卫队全国领袖”装甲掷弹兵师第36装甲掷弹兵团的一辆Sdkfz 234/1型8轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav234_22.jpg","description":"1945年2月，德国战场，隶属德军第25装甲师的一辆Sdkfz 234/1型8轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav234_23.jpg","description":"1944年8月，法国战场诺曼底地区，隶属德国武装党卫军第12“希特勒青年团”装甲师第12党卫军侦察营的一辆Sdkfz 234/2型8轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav234_24.jpg","description":"1944年7月，法国战场诺曼底地区，隶属德国武装党卫军第17“葛兹·冯·伯利辛根”装甲掷弹兵师第17党卫军侦察营的一辆Sdkfz 234/2型8轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav234_25.jpg","description":"1944年8月，法国战场诺曼底地区，隶属德国武装党卫军第10“弗伦茨伯格”装甲师第10党卫军侦察营的一辆Sdkfz 234/3型8轮装甲火力支援车。","caption":""},{"image":"imgs/de/army/de_army_wav234_26.jpg","description":"1944年夏天，法国战场，一辆德军不明单位（车身编号“WH-1751008”）的Sdkfz 234/3型8轮装甲火力支援车。","caption":""},{"image":"imgs/de/army/de_army_wav234_27.jpg","description":"1945年5月，意大利东北部里雅斯特湾，原属德军某部队第5装甲连的一辆Sdkfz 234/4型8轮装甲反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_wav234_28.jpg","description":"1945年4月，德国战场，一辆不明单位的Sdkfz 234/4型8轮装甲反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_wav234_29.jpg","description":"1944年德军一辆不明单位的Sdkfz 234/1型8轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav234_30.jpg","description":"1944年，西线战场法国地区，德军第2装甲师的一辆Sdkfz 234/2型8轮装甲侦察车正在向前线进发。","caption":""},{"image":"imgs/de/army/de_army_wav234_31.jpg","description":"1944年7月，法国战场，一辆德军的Sdkfz 234/2型8轮装甲侦察车正隐蔽在树林中待命。","caption":""},{"image":"imgs/de/army/de_army_wav234_32.jpg","description":"1944年德军一辆不明单位的Sdkfz 234/3型8轮装甲火力支援车。","caption":""},{"image":"imgs/de/army/de_army_wav234_33.jpg","description":"1944年德军一辆不明单位的Sdkfz 234/4型8轮装甲反坦克炮车。","caption":""}]}')}});